"use client"

/** Clean-room AE dashboard surface. Theme tokens only. */

import type { ReactNode } from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { aeCard, liftOnHover, riseItem } from "@/lib/ae-dash"

export type AeCardProps = {
  title?: ReactNode
  action?: ReactNode
  children: ReactNode
  className?: string
  /** Section label for screen readers when there is no visible title. */
  label?: string
  as?: "section" | "article"
}

/** White card with a large radius, soft shadow, staggered rise and hover lift. Put it inside an `AeStagger`. */
export function AeCard({ title, action, children, className, label, as = "section" }: AeCardProps) {
  const reduce = !!useReducedMotion()
  const Tag = as === "article" ? motion.article : motion.section
  return (
    <Tag
      data-slot="ae-card"
      aria-label={typeof title === "string" ? title : label}
      variants={riseItem(reduce)}
      whileHover={liftOnHover(reduce)}
      className={cn(aeCard, "flex min-w-0 flex-col gap-4 p-5 transition-shadow hover:shadow-md", className)}
    >
      {title || action ? (
        <header className="flex min-w-0 items-center justify-between gap-3">
          {title ? <h3 className="min-w-0 truncate text-base font-semibold">{title}</h3> : <span />}
          {action}
        </header>
      ) : null}
      {children}
    </Tag>
  )
}

/** Runs the staggered entrance of every AeCard inside it. */
export function AeStagger({ children, className }: { children: ReactNode; className?: string }) {
  return (
    <motion.div data-slot="ae-stagger" initial="hidden" animate="shown" variants={{ hidden: {}, shown: { transition: { staggerChildren: 0.07 } } }} className={className}>
      {children}
    </motion.div>
  )
}

export function AeEmpty({ children }: { children: ReactNode }) {
  return <p className="rounded-2xl border border-dashed border-border p-6 text-center text-sm text-muted-foreground">{children}</p>
}

export function AeSkeleton({ rows = 3 }: { rows?: number }) {
  return (
    <div role="status" aria-label="Cargando" className="grid gap-3">
      {Array.from({ length: rows }, (_, index) => (
        <div key={index} className="h-6 animate-pulse rounded-full bg-muted motion-reduce:animate-none" />
      ))}
    </div>
  )
}

/**
 * Shared motion and surface helpers for the AE dashboard pieces.
 * Clean-room. Durations only, no colors or theme tokens.
 */
import type { Transition, Variants } from "motion/react"

import { motionPresets } from "@/lib/motion"

/** Parent of a staggered entrance. Children use `riseItem`. */
export const staggerParent: Variants = {
  hidden: {},
  shown: { transition: { staggerChildren: motionPresets.stagger.line, delayChildren: 0.04 } },
}

/** Fade and slide up. With reduced motion the caller passes `reduce` and gets a plain fade. */
export function riseItem(reduce: boolean): Variants {
  return reduce
    ? { hidden: { opacity: 0 }, shown: { opacity: 1, transition: { duration: motionPresets.duration.instant } } }
    : {
        hidden: { opacity: 0, y: 16 },
        shown: { opacity: 1, y: 0, transition: { duration: motionPresets.duration.considered, ease: [...motionPresets.ease.enter] } },
      }
}

/** Grow transition for bars and stroke draws. Zero when motion is reduced. */
export function growTransition(reduce: boolean, index = 0): Transition {
  return reduce ? { duration: 0 } : { duration: motionPresets.duration.considered * 1.5, ease: [...motionPresets.ease.enter], delay: 0.15 + index * motionPresets.stagger.item }
}

/** Hover lift for a card. Off when motion is reduced. */
export function liftOnHover(reduce: boolean) {
  return reduce ? undefined : { y: -3, transition: motionPresets.spring.gentle }
}

/** Base card surface: theme card color, very large radius, soft shadow. */
export const aeCard = "rounded-3xl border border-border/60 bg-card text-card-foreground shadow-sm"

/** Spanish compact number, e.g. 12 400 → "12.4 mil". */
export function compactEs(value: number) {
  return new Intl.NumberFormat("es-MX", { notation: "compact", maximumFractionDigits: 1 }).format(value)
}

export function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}

"use client"

/** Clean-room AE dashboard piece. A floating vertical pill of icon links. Theme tokens only. */

import type { ComponentType, SVGProps } from "react"

import { cn } from "@/lib/utils"

export type FloatingPillItem = { id: string; label: string; icon: ComponentType<SVGProps<SVGSVGElement>>; href?: string }

export type FloatingPillSidebarProps = {
  items: FloatingPillItem[]
  active: string
  onNavigate?: (id: string) => void
  footer?: FloatingPillItem[]
  className?: string
}

function PillLink({ item, current, onNavigate }: { item: FloatingPillItem; current: boolean; onNavigate?: (id: string) => void }) {
  const Icon = item.icon
  return (
    <li>
      <a
        href={item.href ?? `#${item.id}`}
        aria-label={item.label}
        title={item.label}
        aria-current={current ? "page" : undefined}
        onClick={(event) => {
          if (onNavigate) {
            event.preventDefault()
            onNavigate(item.id)
          }
        }}
        className={cn("grid size-11 place-items-center rounded-full outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transition-none", current ? "bg-primary text-primary-foreground shadow-md" : "text-muted-foreground hover:bg-muted hover:text-foreground")}
      >
        <Icon aria-hidden className="size-5" />
      </a>
    </li>
  )
}

export function FloatingPillSidebar({ items, active, onNavigate, footer = [], className }: FloatingPillSidebarProps) {
  return (
    <nav aria-label="Secciones" data-slot="floating-pill-sidebar" className={cn("flex w-fit flex-col items-center justify-between gap-6 rounded-full border border-border/60 bg-card p-2 shadow-md", className)}>
      <ul className="flex flex-col items-center gap-2">
        {items.map((item) => (
          <PillLink key={item.id} item={item} current={item.id === active} onNavigate={onNavigate} />
        ))}
      </ul>
      {footer.length ? (
        <ul className="flex flex-col items-center gap-2">
          {footer.map((item) => (
            <PillLink key={item.id} item={item} current={item.id === active} onNavigate={onNavigate} />
          ))}
        </ul>
      ) : null}
    </nav>
  )
}

"use client"

/** Clean-room AE dashboard piece. Centered pill navigation with a sliding active pill. Theme tokens only. */

import { useId, type ReactNode } from "react"
import { motion, useReducedMotion } from "motion/react"
import { Bell, Search } from "lucide-react"

import { cn } from "@/lib/utils"
import { initials } from "@/lib/ae-dash"

export type PillNavItem = { id: string; label: string; href?: string }

export type PillTopNavProps = {
  brand?: ReactNode
  items: PillNavItem[]
  active: string
  onNavigate?: (id: string) => void
  user?: { name: string }
  unread?: number
  onSearch?: () => void
  onNotifications?: () => void
  className?: string
}

export function PillTopNav({ brand, items, active, onNavigate, user, unread = 0, onSearch, onNotifications, className }: PillTopNavProps) {
  const reduce = !!useReducedMotion()
  const layoutId = useId()
  return (
    <header data-slot="pill-top-nav" className={cn("flex min-w-0 flex-wrap items-center justify-between gap-3", className)}>
      <div className="flex min-w-0 items-center gap-2 text-lg font-bold">{brand}</div>
      <nav aria-label="Principal" className="order-last w-full overflow-x-auto md:order-none md:w-auto">
        <ul className="flex w-max items-center gap-1 rounded-full border border-border/60 bg-card p-1 shadow-sm">
          {items.map((item) => {
            const current = item.id === active
            return (
              <li key={item.id} className="relative">
                {current ? <motion.span layoutId={reduce ? undefined : layoutId} aria-hidden className="absolute inset-0 rounded-full bg-foreground" transition={{ type: "spring", visualDuration: 0.3, bounce: 0.15 }} /> : null}
                <a
                  href={item.href ?? `#${item.id}`}
                  aria-current={current ? "page" : undefined}
                  onClick={(event) => {
                    if (onNavigate) {
                      event.preventDefault()
                      onNavigate(item.id)
                    }
                  }}
                  className={cn("relative block rounded-full px-4 py-2 text-sm font-medium whitespace-nowrap outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring", current ? "text-background" : "text-muted-foreground hover:text-foreground")}
                >
                  {item.label}
                </a>
              </li>
            )
          })}
        </ul>
      </nav>
      <div className="flex items-center gap-2">
        <button type="button" aria-label="Buscar" onClick={onSearch} className="grid size-10 place-items-center rounded-full border border-border/60 bg-card shadow-sm outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring">
          <Search aria-hidden className="size-4" />
        </button>
        <button type="button" aria-label={unread ? `Notificaciones, ${unread} sin leer` : "Notificaciones"} onClick={onNotifications} className="relative grid size-10 place-items-center rounded-full border border-border/60 bg-card shadow-sm outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring">
          <Bell aria-hidden className="size-4" />
          {unread ? <span aria-hidden className="absolute top-2 right-2 size-2 rounded-full bg-primary ring-2 ring-card" /> : null}
        </button>
        {user ? (
          <span role="img" aria-label={user.name} className="grid size-10 place-items-center rounded-full bg-primary text-sm font-semibold text-primary-foreground">
            {initials(user.name)}
          </span>
        ) : null}
      </div>
    </header>
  )
}

"use client"

/** Clean-room AE dashboard piece. Several series as gradient-filled areas with a legend that toggles them. Theme tokens only. */

import { useId, useState } from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { growTransition } from "@/lib/ae-dash"
import { AeCard, AeEmpty } from "@/components/ui/ae/card-shell"

export type AreaSeries = { id: string; label: string; values: number[] }

export type MultiAreaChartCardProps = { title?: string; labels: string[]; series: AreaSeries[]; className?: string }

/** Host chart tokens. The first series takes the accent. */
const tones = ["text-primary", "text-[color:var(--chart-2)]", "text-[color:var(--chart-4)]", "text-[color:var(--chart-5)]"]
const W = 600
const H = 220

function linePath(values: number[], max: number) {
  const last = Math.max(1, values.length - 1)
  return values.map((value, index) => `${index ? "L" : "M"}${((index / last) * W).toFixed(1)} ${(H - 8 - (value / max) * (H - 24)).toFixed(1)}`).join(" ")
}

export function MultiAreaChartCard({ title = "Actividad por mes", labels, series, className }: MultiAreaChartCardProps) {
  const reduce = !!useReducedMotion()
  const id = useId()
  const [hidden, setHidden] = useState<string[]>([])
  const visible = series.filter((item) => !hidden.includes(item.id))
  const max = Math.max(1, ...visible.flatMap((item) => item.values))
  return (
    <AeCard
      title={title}
      className={className}
      action={
        <ul aria-label="Series" className="flex flex-wrap justify-end gap-1.5">
          {series.map((item, index) => {
            const on = !hidden.includes(item.id)
            return (
              <li key={item.id}>
                <button
                  type="button"
                  aria-pressed={on}
                  onClick={() => setHidden((prev) => (on ? [...prev, item.id] : prev.filter((key) => key !== item.id)))}
                  className={cn("inline-flex items-center gap-1.5 rounded-full border border-border/60 px-2.5 py-1 text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring", on ? "text-foreground" : "text-muted-foreground line-through opacity-60")}
                >
                  <span aria-hidden className={cn("size-2 rounded-full bg-current", tones[index % tones.length])} />
                  {item.label}
                </button>
              </li>
            )
          })}
        </ul>
      }
    >
      {visible.length === 0 || labels.length === 0 ? (
        <AeEmpty>Activa al menos una serie.</AeEmpty>
      ) : (
        <figure className="grid gap-2">
          <figcaption className="sr-only">
            {visible.map((item) => `${item.label}: ${item.values.map((value, index) => `${labels[index]} ${value}`).join(", ")}`).join(". ")}
          </figcaption>
          <svg viewBox={`0 0 ${W} ${H}`} className="h-56 w-full overflow-visible" preserveAspectRatio="none" aria-hidden focusable="false">
            {[0.25, 0.5, 0.75, 1].map((step) => (
              <line key={step} x1="0" x2={W} y1={H - 8 - step * (H - 24)} y2={H - 8 - step * (H - 24)} className="stroke-border" strokeDasharray="4 6" vectorEffect="non-scaling-stroke" />
            ))}
            {series.map((item, index) => {
              if (hidden.includes(item.id)) return null
              const d = linePath(item.values, max)
              return (
                <g key={item.id} className={tones[index % tones.length]}>
                  <defs>
                    <linearGradient id={`${id}-${item.id}`} x1="0" x2="0" y1="0" y2="1">
                      <stop offset="0" stopColor="currentColor" stopOpacity="0.28" />
                      <stop offset="1" stopColor="currentColor" stopOpacity="0" />
                    </linearGradient>
                  </defs>
                  <motion.path d={`${d} L${W} ${H} L0 ${H} Z`} fill={`url(#${id}-${item.id})`} initial={{ opacity: reduce ? 1 : 0 }} animate={{ opacity: 1 }} transition={growTransition(reduce, index + 2)} />
                  <motion.path d={d} fill="none" stroke="currentColor" strokeWidth={2.5} strokeLinecap="round" strokeLinejoin="round" initial={{ pathLength: reduce ? 1 : 0 }} animate={{ pathLength: 1 }} transition={growTransition(reduce, index)} />
                </g>
              )
            })}
          </svg>
          <div className="flex justify-between text-xs text-muted-foreground" aria-hidden>
            {labels.map((label) => (
              <span key={label}>{label}</span>
            ))}
          </div>
        </figure>
      )}
    </AeCard>
  )
}

"use client"

/** Clean-room AE dashboard piece. A task list with progress bars. Theme tokens only. */

import { motion, useReducedMotion } from "motion/react"
import { CheckCircle2, Circle } from "lucide-react"

import { cn } from "@/lib/utils"
import { growTransition } from "@/lib/ae-dash"
import { AeCard, AeEmpty } from "@/components/ui/ae/card-shell"

export type ProgressTask = { id: string; title: string; progress: number; due?: string }

export type TaskProgressCardProps = { title?: string; tasks: ProgressTask[]; className?: string }

export function TaskProgressCard({ title = "Tareas", tasks, className }: TaskProgressCardProps) {
  const reduce = !!useReducedMotion()
  const done = tasks.filter((task) => task.progress >= 100).length
  return (
    <AeCard title={title} className={className} action={<span className="rounded-full bg-muted px-2.5 py-1 text-xs font-medium tabular-nums">{done}/{tasks.length}</span>}>
      {tasks.length === 0 ? (
        <AeEmpty>Sin tareas pendientes.</AeEmpty>
      ) : (
        <ul className="grid gap-4">
          {tasks.map((task, index) => {
            const value = Math.max(0, Math.min(100, Math.round(task.progress)))
            const complete = value >= 100
            return (
              <li key={task.id} className="grid min-w-0 gap-2">
                <div className="flex min-w-0 items-start gap-2 text-sm">
                  {complete ? <CheckCircle2 aria-hidden className="mt-0.5 size-4 shrink-0 text-primary" /> : <Circle aria-hidden className="mt-0.5 size-4 shrink-0 text-muted-foreground" />}
                  <span className={cn("min-w-0 flex-1 break-words", complete && "text-muted-foreground line-through")}>{task.title}</span>
                  {task.due ? <span className="shrink-0 text-xs text-muted-foreground">{task.due}</span> : null}
                </div>
                <div role="progressbar" aria-label={task.title} aria-valuemin={0} aria-valuemax={100} aria-valuenow={value} className="ml-6 h-1.5 overflow-hidden rounded-full bg-muted">
                  <motion.div className={cn("h-full rounded-full", complete ? "bg-foreground/60" : "bg-primary")} style={{ originX: 0, width: `${value}%` }} initial={{ scaleX: reduce ? 1 : 0 }} animate={{ scaleX: 1 }} transition={growTransition(reduce, index)} />
                </div>
              </li>
            )
          })}
        </ul>
      )}
    </AeCard>
  )
}

"use client"

/** Clean-room AE dashboard piece. Ranking of advisors. Theme tokens only. */

import { Trophy } from "lucide-react"

import { cn } from "@/lib/utils"
import { initials } from "@/lib/ae-dash"
import { AeCard, AeEmpty } from "@/components/ui/ae/card-shell"

export type Leader = { id: string; name: string; region?: string; score: number; closed?: number }

export type LeaderboardCardProps = { title?: string; leaders: Leader[]; scoreLabel?: string; highlightId?: string; className?: string }

export function LeaderboardCard({ title = "Ranking de asesores", leaders, scoreLabel = "pts", highlightId, className }: LeaderboardCardProps) {
  const sorted = [...leaders].sort((a, b) => b.score - a.score)
  return (
    <AeCard title={title} className={className} action={<Trophy aria-hidden className="size-5 text-primary" />}>
      {sorted.length === 0 ? (
        <AeEmpty>Aún no hay ranking.</AeEmpty>
      ) : (
        <ol className="grid gap-2">
          {sorted.map((leader, index) => {
            const me = leader.id === highlightId
            return (
              <li key={leader.id} aria-current={me ? "true" : undefined} className={cn("flex min-w-0 items-center gap-3 rounded-2xl px-3 py-2.5", index === 0 ? "bg-primary/10" : "bg-muted/50", me && "ring-2 ring-primary")}>
                <span className={cn("grid size-7 shrink-0 place-items-center rounded-full text-xs font-bold tabular-nums", index === 0 ? "bg-primary text-primary-foreground" : "bg-background text-foreground")}>
                  <span className="sr-only">Lugar </span>
                  {index + 1}
                </span>
                <span aria-hidden className="grid size-9 shrink-0 place-items-center rounded-full bg-foreground text-xs font-semibold text-background">{initials(leader.name)}</span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium">{leader.name}</span>
                  {leader.region ? <span className="block truncate text-xs text-muted-foreground">{leader.region}{leader.closed !== undefined ? ` · ${leader.closed} expedientes` : ""}</span> : null}
                </span>
                <span className="shrink-0 text-sm font-bold tabular-nums">
                  {leader.score.toLocaleString("es-MX")} <span className="text-xs font-normal text-muted-foreground">{scoreLabel}</span>
                </span>
              </li>
            )
          })}
        </ol>
      )}
    </AeCard>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { AnimatePresence, motion, useReducedMotion, type Variants } from "motion/react"

import { Avatar, AvatarBadge, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type AvatarGroupMember = {
  name: string
  src?: string
  status?: "online" | "offline"
}

export type AvatarGroupClassNames = {
  root?: string
  slot?: string
  avatar?: string
  overflow?: string
  count?: string
  tip?: string
}

export type AvatarGroupProps = {
  members: AvatarGroupMember[]
  max?: number
  size?: "sm" | "md" | "lg"
  label?: string
  className?: string
  classNames?: AvatarGroupClassNames
}

const rise: Variants = {
  hidden: (direction: number) => ({
    opacity: 0,
    y: `${0.4 * direction}em`,
    filter: `blur(${motionPresets.blur.subtle}px)`,
  }),
  shown: {
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { duration: motionPresets.duration.standard, ease: [...motionPresets.ease.enter] },
  },
  gone: (direction: number) => ({
    opacity: 0,
    y: `${-0.4 * direction}em`,
    filter: `blur(${motionPresets.blur.subtle}px)`,
    transition: { duration: motionPresets.duration.fast, ease: [...motionPresets.ease.standard] },
  }),
}

const fade: Variants = {
  hidden: { opacity: 0, y: 0, filter: "blur(0px)" },
  shown: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
  gone: { opacity: 0, y: 0, filter: "blur(0px)", transition: { duration: motionPresets.duration.instant } },
}

const slotMotion = {
  initial: { width: 0, opacity: 0, scale: 0.9 },
  animate: { width: "auto", opacity: 1, scale: 1 },
  exit: { width: 0, opacity: 0, scale: 0.9 },
}

const pixelSize = { sm: 28, md: 36, lg: 48 } as const
const avatarSize = { sm: "sm", md: "default", lg: "lg" } as const

function initials(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

export function AvatarGroup({
  members,
  max = 4,
  size = "md",
  label = "Team members",
  className,
  classNames,
}: AvatarGroupProps) {
  const reduceMotion = !!useReducedMotion()
  const visible = members.slice(0, Math.max(0, max))
  const overflow = Math.max(0, members.length - visible.length)
  const transition = reduceMotion ? { duration: 0 } : motionPresets.spring.morph
  const [count, setCount] = React.useState({ overflow, direction: 1 })
  if (count.overflow !== overflow) setCount({ overflow, direction: overflow < count.overflow ? -1 : 1 })
  const px = pixelSize[size]
  const stack = visible.length + (overflow > 0 ? 1 : 0)

  return (
    <div
      data-slot="avatar-group"
      role="group"
      aria-label={label}
      style={{ "--count": stack, height: px } as React.CSSProperties}
      className={cn("group/avatars inline-flex min-w-0 items-center ps-1.5", className, classNames?.root)}
    >
      <AnimatePresence initial={false}>
        {visible.map((member, index) => (
          <motion.span
            key={member.name}
            data-slot="avatar-group-slot"
            className={cn(
              "peer relative inline-flex h-full shrink-0 items-center [--aside:0px] hover:z-10",
              "has-[~.peer:hover]:[--aside:-3px] peer-hover:[--aside:3px]",
              classNames?.slot,
            )}
            style={{ "--index": index } as React.CSSProperties}
            {...slotMotion}
            transition={transition}
          >
            <span
              className={cn(
                "group/slot relative inline-flex -ms-1.5 rounded-full [--fan:0px] [--rise:0px] outline-none",
                "translate-x-[calc(var(--fan)+var(--aside))] translate-y-(--rise) transition-transform duration-300 ease-out",
                "group-hover/avatars:[--fan:calc((var(--index)-(var(--count)-1)/2)*4px)]",
                "group-hover/slot:[--rise:-2px] focus-visible:z-10 motion-reduce:!transform-none motion-reduce:transition-none",
              )}
            >
              <Avatar
                data-slot="avatar-group-avatar"
                size={avatarSize[size]}
                style={{ width: px, height: px }}
                role="img"
                tabIndex={0}
                aria-label={`${member.name}${member.status ? `, ${member.status}` : ""}`}
                className={cn("ring-2 ring-background outline-none focus-visible:ring-ring", classNames?.avatar)}
              >
                {member.src ? <AvatarImage src={member.src} alt="" /> : null}
                <AvatarFallback>{initials(member.name)}</AvatarFallback>
                <AnimatePresence initial={false}>
                  {member.status ? (
                    <motion.span
                      key={member.status}
                      className="absolute end-0 bottom-0 z-10 grid leading-none"
                      initial={{ opacity: 0, scale: 0.6 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.6, transition: { duration: reduceMotion ? 0 : motionPresets.duration.fast } }}
                      transition={reduceMotion ? { duration: 0 } : motionPresets.spring.snappy}
                    >
                      <AvatarBadge className={cn("static!", member.status === "offline" && "bg-muted-foreground")} />
                    </motion.span>
                  ) : null}
                </AnimatePresence>
              </Avatar>
              <span
                data-slot="avatar-group-tip"
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute bottom-[calc(100%+8px)] left-1/2 z-10 max-w-64 -translate-x-1/2 translate-y-0.75 truncate rounded-full bg-foreground px-2 py-1 text-xs font-medium text-background opacity-0 transition duration-150",
                  "group-hover/slot:translate-y-0 group-hover/slot:opacity-100 group-focus-within/slot:translate-y-0 group-focus-within/slot:opacity-100 motion-reduce:transition-none",
                  classNames?.tip,
                )}
              >
                {member.name}
              </span>
            </span>
          </motion.span>
        ))}
        {overflow > 0 ? (
          <motion.span
            key="overflow"
            data-slot="avatar-group-slot"
            className={cn(
              "peer relative inline-flex h-full shrink-0 items-center [--aside:0px] hover:z-10",
              "has-[~.peer:hover]:[--aside:-3px] peer-hover:[--aside:3px]",
              classNames?.slot,
            )}
            style={{ "--index": visible.length } as React.CSSProperties}
            {...slotMotion}
            transition={transition}
          >
            <span
              tabIndex={0}
              data-slot="avatar-group-overflow"
              role="img"
              aria-label={`${overflow} more ${label.toLowerCase()}`}
              style={{ width: px, height: px }}
              className={cn(
                "group/slot relative -ms-1.5 inline-grid place-items-center overflow-hidden rounded-full bg-muted font-medium text-muted-foreground tabular-nums ring-2 ring-background outline-none",
                "[--fan:0px] [--rise:0px] translate-x-[calc(var(--fan)+var(--aside))] translate-y-(--rise) transition-transform duration-300 ease-out",
                "group-hover/avatars:[--fan:calc((var(--index)-(var(--count)-1)/2)*4px)] group-hover/slot:[--rise:-2px]",
                "motion-reduce:!transform-none motion-reduce:transition-none",
                size === "sm" ? "text-[10px]" : size === "lg" ? "text-sm" : "text-xs",
                classNames?.overflow,
              )}
            >
              <AnimatePresence mode="popLayout" initial={false} custom={count.direction}>
                <motion.span
                  key={overflow}
                  data-slot="avatar-group-count"
                  custom={count.direction}
                  variants={reduceMotion ? fade : rise}
                  initial="hidden"
                  animate="shown"
                  exit="gone"
                  aria-hidden="true"
                  className={cn("inline-block", classNames?.count)}
                >
                  +{overflow}
                </motion.span>
              </AnimatePresence>
            </span>
          </motion.span>
        ) : null}
      </AnimatePresence>
    </div>
  )
}
